from typing import List, Optional, Tuple
from dataclasses import dataclass
import enum

class ResultType(enum.Enum):
    SUCCESS = "success"
    FAILURE = "failure"

@dataclass
class StepResponse:
    result: ResultType

@dataclass
class CreditChargesPayment:
    txn_id: str
    open_balance: float
    linked_payment_amount: str = ""

class PaymentChargesTableAction:
    @staticmethod
    def full_credits_table_update(credits_table: List[CreditChargesPayment]) -> None:
        """Simulate the Redux action dispatch"""
        pass

class PaymentTableSelectors:
    @staticmethod
    def get_credits() -> List[CreditChargesPayment]:
        """Simulate Redux selector for getting credits"""
        return []

    @staticmethod
    def get_total_of_charges_table() -> float:
        """Simulate Redux selector for getting total charges"""
        return 0.0

def validate_and_process_credit(
    credit: CreditChargesPayment, 
    remaining_balance: float
) -> Tuple[Optional[CreditChargesPayment], float, bool]:
    """
    Simplified validation and processing for a single credit.

    Returns:
        Tuple[Optional[CreditChargesPayment], float, bool]: 
        (updated_credit, new_remaining_balance, was_updated)
        Returns (None, remaining_balance, False) for invalid credits
    """
    # Basic type validation
    if not isinstance(credit.txn_id, str) or not credit.txn_id.strip():
        return None, remaining_balance, False

    if not isinstance(credit.open_balance, (int, float)) or credit.open_balance < 0:
        return None, remaining_balance, False

    if not isinstance(credit.linked_payment_amount, str):
        return None, remaining_balance, False

    # Skip if no linked payment to process
    if not credit.linked_payment_amount.strip():
        return credit, remaining_balance, False

    # Calculate new amount based on remaining balance
    if remaining_balance >= credit.open_balance:
        new_amount = str(credit.open_balance)
        new_remaining = remaining_balance - credit.open_balance
    elif remaining_balance > 0:
        new_amount = str(remaining_balance)
        new_remaining = 0
    else:
        new_amount = ""
        new_remaining = remaining_balance

    # Only update if amount changed
    if credit.linked_payment_amount == new_amount:
        return credit, new_remaining, False

    # Create updated credit
    updated_credit = CreditChargesPayment(
        txn_id=credit.txn_id,
        open_balance=credit.open_balance,
        linked_payment_amount=new_amount
    )

    return updated_credit, new_remaining, True

def outstanding_transactions_handler() -> StepResponse:
    """
    Main handler with improved error handling for edge cases.

    Key improvements:
    1. Comprehensive validation of credit_table_lines data type
    2. Graceful handling of invalid data in the list
    3. Simplified validation logic
    4. Clear error reporting

    Returns:
        StepResponse: Result of the operation
    """
    try:
        # Get data with robust type checking
        credit_table_lines = PaymentTableSelectors.get_credits()
        if not isinstance(credit_table_lines, list):
            return StepResponse(result=ResultType.FAILURE)

        total_charges = PaymentTableSelectors.get_total_of_charges_table()
        if not isinstance(total_charges, (int, float)) or total_charges < 0:
            return StepResponse(result=ResultType.FAILURE)

        # Early return for empty data
        if not credit_table_lines or total_charges <= 0:
            PaymentChargesTableAction.full_credits_table_update([])
            return StepResponse(result=ResultType.SUCCESS)

        # Process credits
        remaining_balance = float(total_charges)
        updated_credits: List[CreditChargesPayment] = []
        has_updates = False

        for credit in credit_table_lines:
            if not isinstance(credit, CreditChargesPayment):
                continue

            result, remaining_balance, was_updated = validate_and_process_credit(
                credit, remaining_balance
            )

            if result is None:
                continue

            updated_credits.append(result)
            if was_updated:
                has_updates = True

        # Dispatch update if we have updates
        if has_updates:
            PaymentChargesTableAction.full_credits_table_update(updated_credits)

        return StepResponse(result=ResultType.SUCCESS)

    except Exception:
        return StepResponse(result=ResultType.FAILURE)

# Example usage
if __name__ == "__main__":
    class TestSelectors(PaymentTableSelectors):
        @staticmethod
        def get_credits() -> List[CreditChargesPayment]:
            return [
                CreditChargesPayment(txn_id="1", open_balance=100.0, linked_payment_amount="50"),
                CreditChargesPayment(txn_id="2", open_balance=200.0, linked_payment_amount=""),
                CreditChargesPayment(txn_id="3", open_balance=150.0, linked_payment_amount="100"),
            ]

        @staticmethod
        def get_total_of_charges_table() -> float:
            return 250.0

    PaymentTableSelectors = TestSelectors

    result = outstanding_transactions_handler()
    print(f"Result: {result.result.value}")

