                    const pageText = document.body.innerText.toLowerCase();
                    return successTexts.some(text => pageText.includes(text));
                },

                // Form disappeared
                () => document.querySelectorAll('form').length === 0,

                // New page loaded
                () => document.readyState === 'complete' && 
                      performance.getEntriesByType('navigation')[0]?.type === 'reload'
            ];

            // Count successful indicators
            const successCount = indicators.filter(indicator => {
                try {
                    return indicator();
                } catch (e) {
                    return false;
                }
            }).length;

            console.log(`Action verification: ${successCount}/${indicators.length} indicators passed`);
            return successCount >= 2; // Require at least 2 indicators
        }

        // Utility methods
        async waitForSelector(selector, timeout = 1000) {
            return new Promise((resolve) => {
                const element = document.querySelector(selector);
                if (element) {
                    resolve(element);
                    return;
                }

                const observer = new MutationObserver(() => {
                    const element = document.querySelector(selector);
                    if (element) {
                        observer.disconnect();
                        resolve(element);
                    }
                });

                observer.observe(document.body, {
                    childList: true,
                    subtree: true
                });

                setTimeout(() => {
                    observer.disconnect();
                    resolve(null);
                }, timeout);
            });
        }

        isElementInteractable(element) {
            if (!element) return false;
            if (!this.isElementVisible(element)) return false;
            if (element.disabled) return false;

            // Check if element is not covered by another element
            const rect = element.getBoundingClientRect();
            const topElement = document.elementFromPoint(
                rect.left + rect.width / 2,
                rect.top + rect.height / 2
            );

            return element.contains(topElement) || topElement === element;
        }

        isElementVisible(element) {
            const style = window.getComputedStyle(element);
            return style.display !== 'none' &&
                   style.visibility !== 'hidden' &&
                   style.opacity !== '0' &&
                   element.offsetWidth > 0 &&
                   element.offsetHeight > 0;
        }

        isInViewport(element) {
            const rect = element.getBoundingClientRect();
            return (
                rect.top >= 0 &&
                rect.left >= 0 &&
                rect.bottom <= (window.innerHeight || document.documentElement.clientHeight) &&
                rect.right <= (window.innerWidth || document.documentElement.clientWidth)
            );
        }

        hasEventListeners(element, eventType) {
            // This is a simplified check - in reality, we can't access all listeners
            return !!element.onclick || 
                   element.getAttribute(`on${eventType}`) ||
                   element.hasAttribute(`data-${eventType}`);
        }

        async attemptClickWithMonitoring(element) {
            try {
                // Scroll element into view
                element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                await this.delay(500);

                // Click with visual feedback simulation
                this.simulateVisualFeedback(element);
                element.click();

                await this.delay(1000);
                return { success: true, element: element };
            } catch (error) {
                console.log('Click attempt failed:', error);
                return { success: false, element: element, error: error.message };
            }
        }

        simulateVisualFeedback(element) {
            // Add temporary visual feedback
            const originalStyle = element.style.cssText;
            element.style.transition = 'background-color 0.3s';
            element.style.backgroundColor = '#4CAF50';

            // Remove feedback after delay
            setTimeout(() => {
                element.style.cssText = originalStyle;
            }, 300);
        }

        simulateEnterKey(element) {
            const enterEvent = new KeyboardEvent('keydown', {
                key: 'Enter',
                code: 'Enter',
                keyCode: 13,
                which: 13,
                bubbles: true
            });
            element.dispatchEvent(enterEvent);

            // Also send keyup
            setTimeout(() => {
                const keyupEvent = new KeyboardEvent('keyup', {
                    key: 'Enter',
                    code: 'Enter',
                    keyCode: 13,
                    which: 13,
                    bubbles: true
                });
                element.dispatchEvent(keyupEvent);
            }, 50);
        }

        delay(ms) {
            return new Promise(resolve => setTimeout(resolve, ms));
        }
    }

    // Initialize when page is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => {
            new EnhancedElementFinder().findAndClickSubmit();
        });
    } else {
        new EnhancedElementFinder().findAndClickSubmit();
    }
})();
