        isWithinTimeRange() {
            const now = new Date();
            const hours = now.getHours();
            const minutes = now.getMinutes();
            const currentMinutes = hours * 60 + minutes;

            const startMinutes = CONFIG.TIME_RANGE.start.hour * 60 + CONFIG.TIME_RANGE.start.minute;
            const endMinutes = CONFIG.TIME_RANGE.end.hour * 60 + CONFIG.TIME_RANGE.end.minute;

            if (hours >= 22 || hours < 3) {
                if (hours >= 22) {
                    return currentMinutes >= startMinutes;
                } else {
                    return currentMinutes <= endMinutes;
                }
            }
            return false;
