            console.log('Starting text check loop...');

            while (this.state.textChecking && !this.state.scriptComplete) {
                const hasText = await this.checkForTargetText();

                if (hasText) {
                    console.log('Target text found. Waiting 5 seconds...');
                    await this.delay(CONFIG.TEXT_CHECK_DELAY);
                    window.location.reload();
