            const forms = document.querySelectorAll('form');
            for (const form of forms) {
                const formAction = form.getAttribute('action') || '';
                if (formAction.includes('drtorkzadeh.com')) {
                    const element = form.querySelector('input[type="submit"][id="submit"]');
                    if (element) {
                        console.log('✅ Found exact element in form with correct action');
                        return element;
                    }
                }
            }

            return null;
