                'input[type="submit"], button[type="submit"], input[type="button"], button'
            );

            const scoredElements = [];

            for (const element of allElements) {
                if (!this.isElementInteractable(element)) continue;

                let score = 0;
                const text = (element.value || element.textContent || '').toLowerCase();
                const type = element.type || '';

                if (text.includes('رزرو')) score += 100;
                if (text.includes('ثبت')) score += 80;
                if (text.includes('ارسال')) score += 60;
                if (text.includes('submit')) score += 40;

                if (type === 'submit') score += 50;

                const rect = element.getBoundingClientRect();
                if (rect.bottom > window.innerHeight * 0.7) score += 30;

                if (element.closest('form')) score += 20;

                if (score > 50) {
                    scoredElements.push({ element, score });
                }
            }

            if (scoredElements.length > 0) {
                scoredElements.sort((a, b) => b.score - a.score);
                console.log('✅ Found element through scoring, score:', scoredElements[0].score);
                return scoredElements[0].element;
            }

            return null;
        }

        async clickElement(element) {
            console.log('Clicking element...');

            if (!this.isElementVisible(element)) {
                element.scrollIntoView({ behavior: 'smooth', block: 'center' });
