        [source_strengths, gamma] = solve_flow(panels, V_inf, alpha_rad);

        % Compute lift coefficient
        chord = max(x_points) - min(x_points);
        Cl = 2 * gamma / (V_inf * chord);
        Cl_values(i) = Cl;

        % Calculate error
        if i > 1
