end

%% GET AIRFOIL GEOMETRY
function [x_points, y_points] = get_airfoil_geometry()
    fprintf('AIRFOIL GEOMETRY INPUT:\n');
    fprintf('1. Use default NACA 0012 airfoil\n');
    fprintf('2. Load from text file\n');

    choice = input('Enter choice (1 or 2): ', 's');

    if strcmp(choice, '2')
        filename = input('Enter filename: ', 's');
        if ~exist(filename, 'file')
            fprintf('File not found. Using default airfoil.\n');
            [x_points, y_points] = create_default_airfoil();
        else
            [x_points, y_points] = load_airfoil_points(filename);
        end
    else
        [x_points, y_points] = create_default_airfoil();
    end
end

%% LOAD AIRFOIL POINTS FROM FILE
function [x_points, y_points] = load_airfoil_points(filename)
    data = load(filename);
    x_points = data(:, 1);
    y_points = data(:, 2);
    fprintf('Loaded %d points from %s\n', length(x_points), filename);
end

%% CREATE DEFAULT AIRFOIL (NACA 0012)
function [x_points, y_points] = create_default_airfoil()
    n_points = 100;
    theta = linspace(0, 2*pi, n_points);
    x_points = 0.5 * (1 + cos(theta));
    y_points = 0.12 * sin(theta);
    fprintf('Using default NACA 0012 airfoil\n');
end

%% GET FLOW CONDITIONS
function [V_inf, alpha_deg] = get_flow_conditions()
    fprintf('\n=== FLOW CONDITIONS ===\n');
    V_inf = input('Enter free stream velocity (m/s): ');
    alpha_deg = input('Enter angle of attack (degrees): ');
end

%% CREATE PANELS FROM AIRFOIL POINTS
function panels = create_panels(x_points, y_points, n_panels)
    % Resample points if needed
    if n_panels ~= length(x_points) - 1
        t_original = linspace(0, 1, length(x_points));
        t_new = linspace(0, 1, n_panels + 1);
        x_points = interp1(t_original, x_points, t_new);
        y_points = interp1(t_original, y_points, t_new);
    end

    % Initialize panels structure
    panels = struct('xa', {}, 'ya', {}, 'xb', {}, 'yb', {}, ...
                    'xc', {}, 'yc', {}, 'length', {}, 'theta', {});

    % Create panels
    for i = 1:n_panels
        panels(i).xa = x_points(i);
        panels(i).ya = y_points(i);
        panels(i).xb = x_points(i+1);
        panels(i).yb = y_points(i+1);
        panels(i).xc = (x_points(i) + x_points(i+1)) / 2;
        panels(i).yc = (y_points(i) + y_points(i+1)) / 2;
        panels(i).length = sqrt((x_points(i+1) - x_points(i))^2 + ...
                               (y_points(i+1) - y_points(i))^2);
        panels(i).theta = atan2(y_points(i+1) - y_points(i), ...
                               x_points(i+1) - x_points(i));
    end

    fprintf('Created %d panels\n', n_panels);
end

%% SOLVE FLOW FOR SOURCE STRENGTHS AND VORTEX STRENGTH
function [source_strengths, gamma] = solve_flow(panels, V_inf, alpha_rad)
    n_panels = length(panels);

    % Initialize matrices
    A = zeros(n_panels + 1, n_panels + 1);
    b = zeros(n_panels + 1, 1);

    % Compute influence coefficients
    for i = 1:n_panels
        for j = 1:n_panels
            if i == j
                A(i, j) = 0.5;
            else
                % Transform to panel j coordinates
                X = (panels(i).xc - panels(j).xa) * cos(panels(j).theta) + ...
                    (panels(i).yc - panels(j).ya) * sin(panels(j).theta);
                Y = -(panels(i).xc - panels(j).xa) * sin(panels(j).theta) + ...
                     (panels(i).yc - panels(j).ya) * cos(panels(j].theta);
                L = panels(j).length;

                % Compute influence coefficient
                I = compute_I_integral(X, Y, L);
                A(i, j) = I / (2 * pi);
            end
        end

        % Kutta condition column
        A(i, n_panels + 1) = 1.0;

        % RHS for boundary condition
        b(i) = -V_inf * cos(panels(i).theta - alpha_rad);
    end

    % Kutta condition row
    A(n_panels + 1, 1) = 1.0;
    A(n_panels + 1, n_panels) = 1.0;
    A(n_panels + 1, n_panels + 1) = 0.0;
    b(n_panels + 1) = 0.0;

    % Solve linear system
    q = A \ b;

    % Extract results
    source_strengths = q(1:n_panels);
    gamma = q(n_panels + 1);

    fprintf('Solved flow: Gamma = %.6f\n', gamma);
end

%% COMPUTE I INTEGRAL FOR SOURCE PANEL
function I = compute_I_integral(X, Y, L)
    if abs(Y) < 1e-12
        if X < 0
            I = 0;
        elseif X > L
            I = pi;
        else
            I = pi/2;
        end
    else
        term1 = (X - L) * atan2(Y, X - L) - X * atan2(Y, X);
        term2 = 0.5 * Y * log(((X - L)^2 + Y^2) / (X^2 + Y^2));
        I = term1 + term2;
    end
end

%% COMPUTE PRESSURE COEFFICIENT ON EACH PANEL
function Cp = compute_pressure_coefficient(panels, source_strengths, gamma, V_inf, alpha_rad)
    n_panels = length(panels);
    Cp = zeros(n_panels, 1);

    for i = 1:n_panels
        % Compute velocity at control point
        [u, v] = compute_velocity(panels(i).xc, panels(i).yc, panels, ...
                                 source_strengths, gamma, V_inf, alpha_rad);

        % Tangential velocity
        V = u * cos(panels(i).theta) + v * sin(panels(i).theta);

        % Pressure coefficient
        Cp(i) = 1 - (V / V_inf)^2;
    end
end

%% PLOT RESULTS WITH COMPARISON
function plot_results(panels, x_points, y_points, Cp, V_inf, alpha_deg, Cl, Cl_theory)
    figure('Position', [100, 100, 1200, 900]);

    % Panel 1: Airfoil geometry
    subplot(2, 2, 1);
    plot(x_points, y_points, 'k-', 'LineWidth', 2);
    hold on;
    plot(x_points, y_points, 'ro', 'MarkerSize', 3);
    xlabel('x');
    ylabel('y');
    title('Airfoil Geometry');
    axis equal;
    grid on;

    % Panel 2: Pressure coefficient
    subplot(2, 2, 2);
    xc = [panels.xc];
    plot(xc, Cp, 'b-', 'LineWidth', 2);
    xlabel('x/c');
    ylabel('Cp');
    title('Pressure Coefficient Distribution');
    set(gca, 'YDir', 'reverse');
    grid on;

    % Panel 3: Comparison with thin airfoil theory
    subplot(2, 2, 3);
    theta = linspace(0, pi, length(panels));
    x_theory = 0.5 * (1 - cos(theta));
    Cp_theory = 1 - 4 * sin(theta).^2 .* (sin(alpha_rad)./sin(theta) + cos(alpha_rad)).^2;

    plot(x_theory, Cp_theory, 'r--', 'LineWidth', 2, 'DisplayName', 'Thin Airfoil Theory');
    hold on;
    plot(xc, Cp, 'b-', 'LineWidth', 1, 'DisplayName', 'Panel Method');
    xlabel('x/c');
    ylabel('Cp');
