function [u, v] = compute_velocity(x, y, panels, source_strengths, gamma, V_inf, alpha_rad)
    u = V_inf * cos(alpha_rad);
    v = V_inf * sin(alpha_rad);

    for j = 1:length(panels)
        % Transform to panel j coordinates
        X = (x - panels(j).xa) * cos(panels(j).theta) + ...
            (y - panels(j).ya) * sin(panels(j).theta);
        Y = -(x - panels(j).xa) * sin(panels(j).theta) + ...
             (y - panels(j).ya) * cos(panels(j).theta);
        L = panels(j).length;

        % Compute integrals
        I = compute_I_integral(X, Y, L);
        J = compute_J_integral(X, Y, L);

        % Velocity in panel coordinates
        u_p = source_strengths(j) * I / (2 * pi);
        v_p = source_strengths(j) * J / (2 * pi) + gamma / (2 * pi);

        % Transform back to global coordinates
        u = u + u_p * cos(panels(j).theta) - v_p * sin(panels(j).theta);
        v = v + u_p * sin(panels(j).theta) + v_p * cos(panels(j).theta);
    end
end

%% COMPUTE J INTEGRAL FOR VORTEX PANEL
function J = compute_J_integral(X, Y, L)
    if abs(Y) < 1e-12
        J = 0;
    else
        J = 0.5 * log(((X - L)^2 + Y^2) / (X^2 + Y^2));
    end
end

