using namespace std;

template<typename T>
class MatrixMinorCalculator {
private:
    vector<vector<T>> data;
    size_t n;

    // Buffer for minor matrix to avoid repeated allocations
    mutable vector<vector<T>> minor_buffer;

public:
    MatrixMinorCalculator(const vector<vector<T>>& mat) : data(mat), n(mat.size()) {
