        if (row >= n || col >= n) {
            throw out_of_range("Indices out of bounds");
        }

        // Edge cases
        if (n == 1) return static_cast<T>(1);
        if (n == 2) return data[1-row][1-col];

        // Create minor matrix using pre-allocated buffer
        size_t minor_i = 0;
        for (size_t i = 0; i < n; ++i) {
            if (i == row) continue;

            size_t minor_j = 0;
            for (size_t j = 0; j < n; ++j) {
                if (j == col) continue;
                minor_buffer[minor_i][minor_j++] = data[i][j];
            }
            ++minor_i;
        }

        return determinantOptimized(minor_buffer);
    }

private:
    void validateMatrix() const {
        if (n == 0) throw invalid_argument("Matrix cannot be empty");
        for (size_t i = 0; i < n; ++i) {
            if (data[i].size() != n) {
                throw invalid_argument("Matrix must be square");
            }
        }
    }

    T determinantOptimized(const vector<vector<T>>& mat) const {
        size_t m = mat.size();

        // Optimized base cases
        if (m == 1) return mat[0][0];
        if (m == 2) return mat[0][0] * mat[1][1] - mat[0][1] * mat[1][0];
        if (m == 3) {
            // Sarrus' rule for 3x3
            return mat[0][0] * mat[1][1] * mat[2][2] +
                   mat[0][1] * mat[1][2] * mat[2][0] +
                   mat[0][2] * mat[1][0] * mat[2][1] -
                   mat[0][2] * mat[1][1] * mat[2][0] -
                   mat[0][1] * mat[1][0] * mat[2][2] -
                   mat[0][0] * mat[1][2] * mat[2][1];
        }

        // Find row with most zeros for efficiency
        size_t best_row = 0;
        size_t max_zeros = 0;
        for (size_t i = 0; i < m; ++i) {
            size_t zeros = 0;
            for (size_t j = 0; j < m; ++j) {
                if (abs(mat[i][j]) < 1e-12) ++zeros;
            }
            if (zeros > max_zeros) {
                max_zeros = zeros;
                best_row = i;
            }
        }

        T det = 0;

        // Expand along best_row
        for (size_t j = 0; j < m; ++j) {
            if (abs(mat[best_row][j]) < 1e-12) continue;

            // Create minor matrix efficiently
            vector<vector<T>> minor_mat(m-1, vector<T>(m-1));
            size_t minor_i = 0;
            for (size_t i = 0; i < m; ++i) {
                if (i == best_row) continue;

                size_t minor_j = 0;
                for (size_t k = 0; k < m; ++k) {
                    if (k == j) continue;
                    minor_mat[minor_i][minor_j++] = mat[i][k];
                }
                ++minor_i;
            }

            // Compute cofactor
            T sign = (best_row + j) % 2 == 0 ? 1 : -1;
            det += sign * mat[best_row][j] * determinantOptimized(minor_mat);
        }

        return det;
    }
};

