```cpp
#include <vector>
#include <cmath>
#include <algorithm>
#include <stdexcept>
#include <iostream>
#include <memory>
#include <numeric>
#include <functional>
#include <unordered_map>

template<typename T>
class MatrixMinorCalculator {
private:
    std::vector<std::vector<T>> data;
    size_t n;

    // Pre-allocated buffers for performance
    mutable std::vector<std::vector<T>> minor_buffer;
    mutable std::vector<T> temp_row;

    // Cache for determinant calculations
    mutable std::unordered_map<size_t, T> det_cache;

public:
    MatrixMinorCalculator(const std::vector<std::vector<T>>& mat) 
        : data(mat), n(mat.size()) {
        validateMatrix();
        // Pre-allocate buffers
        if (n > 1) {
            minor_buffer.resize(n-1, std::vector<T>(n-1));
            temp_row.resize(n-1);
        }
    }

    // Optimized minor determinant calculation
    T minorDeterminant(size_t row, size_t col) const {
        // Validate indices
        if (row >= n || col >= n) {
            throw std::out_of_range("Indices out of bounds");
        }

        // Edge cases
        if (n == 1) return static_cast<T>(1);
        if (n == 2) return data[1-row][1-col];

        // Create minor matrix using pre-allocated buffer
        size_t minor_i = 0;
        for (size_t i = 0; i < n; ++i) {
            if (i == row) continue;

            const auto& src_row = data[i];
            std::copy_if(src_row.begin(), src_row.end(), minor_buffer[minor_i].begin(), 
                [j = size_t(0), col](auto) mutable { return j++ != col; });
            ++minor_i;
        }

        // Compute determinant with optimal method selection
        return computeDeterminant(minor_buffer);
    }

private:
    void validateMatrix() const {
        if (n == 0) throw std::invalid_argument("Matrix cannot be empty");

        // Use STL algorithm to check squareness
        bool is_square = std::all_of(data.begin(), data.end(),
            [this](const auto& row) { return row.size() == n; });

        if (!is_square) {
            throw std::invalid_argument("Matrix must be square");
        }
    }

    T computeDeterminant(const std::vector<std::vector<T>>& mat) const {
        size_t m = mat.size();

        // Hash the matrix for caching
        size_t hash = matrixHash(mat);
        if (det_cache.find(hash) != det_cache.end()) {
            return det_cache[hash];
        }

        T result = 0;

        // Method selection based on size
        if (m <= 4) {
            result = smallMatrixDeterminant(mat);
        } else {
            result = luDeterminant(mat);
        }

        // Cache the result
        det_cache[hash] = result;
        return result;
    }

    T smallMatrixDeterminant(const std::vector<std::vector<T>>& mat) const {
        size_t m = mat.size();

        // Optimized base cases
        switch (m) {
            case 1: return mat[0][0];
            case 2: 
                return mat[0][0] * mat[1][1] - mat[0][1] * mat[1][0];
            case 3: {
                // Sarrus' rule
                const auto& r0 = mat[0];
                const auto& r1 = mat[1];
                const auto& r2 = mat[2];
                return r0[0]*(r1[1]*r2[2] - r1[2]*r2[1]) 
                     - r0[1]*(r1[0]*r2[2] - r1[2]*r2[0]) 
                     + r0[2]*(r1[0]*r2[1] - r1[1]*r2[0]);
            }
            case 4: {
                // Laplace expansion optimized for 4x4
                const auto& r0 = mat[0];
                const auto& r1 = mat[1];
                const auto& r2 = mat[2];
                const auto& r3 = mat[3];

                T det = r0[0] * (r1[1]*(r2[2]*r3[3] - r2[3]*r3[2]) - r1[2]*(r2[1]*r3[3] - r2[3]*r3[1]) + r1[3]*(r2[1]*r3[2] - r2[2]*r3[1]))
                      - r0[1] * (r1[0]*(r2[2]*r3[3] - r2[3]*r3[2]) - r1[2]*(r2[0]*r3[3] - r2[3]*r3[0]) + r1[3]*(r2[0]*r3[2] - r2[2]*r3[0]))
                      + r0[2] * (r1[0]*(r2[1]*r3[3] - r2[3]*r3[1]) - r1[1]*(r2[0]*r3[3] - r2[3]*r3[0]) + r1[3]*(r2[0]*r3[1] - r2[1]*r3[0]))
                      - r0[3] * (r1[0]*(r2[1]*r3[2] - r2[2]*r3[1]) - r1[1]*(r2[0]*r3[2] - r2[2]*r3[0]) + r1[2]*(r2[0]*r3[1] - r2[1]*r3[0]));
                return det;
            }
            default: 
                throw std::logic_error("Invalid matrix size for small matrix method");
        }
    }

    T luDeterminant(const std::vector<std::vector<T>>& mat) const {
        size_t m = mat.size();
        std::vector<std::vector<T>> lu = mat;
        std::vector<size_t> pivot(m);

        T det = 1;
        int sign = 1;

        // LU decomposition with partial pivoting
        for (size_t k = 0; k < m; ++k) {
            // Find pivot element
            size_t max_row = k;
            T max_val = std::abs(lu[k][k]);

            for (size_t i = k+1; i < m; ++i) {
                T val = std::abs(lu[i][k]);
                if (val > max_val) {
                    max_val = val;
                    max_row = i;
                }
            }

            // Swap rows if needed
            if (max_row != k) {
                std::swap(lu[k], lu[max_row]);
                sign *= -1;
            }

            // Check for singular matrix
            if (std::abs(lu[k][k]) < 1e-12) {
                return 0;
            }

            // Perform elimination
            for (size_t i = k+1; i < m; ++i) {
                lu[i][k] /= lu[k][k];
                for (size_t j = k+1; j < m; ++j) {
                    lu[i][j] -= lu[i][k] * lu[k][j];
                }
            }
        }

        // Compute determinant from diagonal
        for (size_t i = 0; i < m; ++i) {
            det *= lu[i][i];
        }

        return det * sign;
    }

    size_t matrixHash(const std::vector<std::vector<T>>& mat) const {
        size_t seed = mat.size();
        for (const auto& row : mat) {
            for (const auto& val : row) {
                seed ^= std::hash<T>{}(val) + 0x9e3779b9 + (seed << 6) + (seed >> 2);
            }
        }
        return seed;
    }
};

// Example usage
int main() {
    std::vector<std::vector<double>> matrix = {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };

    MatrixMinorCalculator<double> calc(matrix);

    try {
        std::cout << "Minor determinant (0,0): " << calc.minorDeterminant(0, 0) << std::endl;
        std::cout << "Minor determinant (1,1): " << calc.minorDeterminant(1, 1) << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
