import numpy as np
import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import Dataset, DataLoader
import os
import gc
import psutil
import warnings
from typing import List, Tuple, Optional, Dict, Any

warnings.filterwarnings('ignore')

class MemoryMonitor:
    @staticmethod
    def get_memory_usage() -> Dict[str, float]:
        process = psutil.Process(os.getpid())
        memory_info = process.memory_info()
        return {
            'rss_mb': memory_info.rss / 1024**2,
            'available_mb': psutil.virtual_memory().available / 1024**2
        }

    @staticmethod
    def clear_cache():
        torch.cuda.empty_cache() if torch.cuda.is_available() else None
        gc.collect()

class ThreeDArrayDataset(Dataset):
    def __init__(self, data_pairs: List[Tuple[int, np.ndarray]]):
        self.tokens = [pair[0] for pair in data_pairs]
        self.arrays = [pair[1] for pair in data_pairs]

    def __len__(self):
        return len(self.tokens)

    def __getitem__(self, idx):
        return self.tokens[idx], self.arrays[idx].astype(np.float32)

class ThreeDArrayGenerator(nn.Module):
    def __init__(self, vocab_size: int, array_shape: Tuple[int, int, int] = (32, 32, 32)):
        super().__init__()
        self.device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
        self.array_shape = array_shape

        self.token_embedding = nn.Embedding(vocab_size, 128)
        self.encoder = nn.Sequential(
            nn.Linear(128, 256),
            nn.ReLU(),
            nn.Linear(256, 256),
            nn.ReLU()
        )
        self.decoder = nn.Sequential(
            nn.Linear(256, self.array_shape[0] * self.array_shape[1] * self.array_shape[2]),
            nn.Sigmoid()
        )
        self.to(self.device)

    def forward(self, tokens: torch.Tensor) -> torch.Tensor:
        embedded = self.token_embedding(tokens)
        encoded = self.encoder(embedded)
        flat_array = self.decoder(encoded)
        return flat_array.view(tokens.size(0), *self.array_shape)

class ThreeDArrayNetwork:
    def __init__(self, vocab_size: int, array_shape: Tuple[int, int, int] = (32, 32, 32)):
        self.device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
        self.model = ThreeDArrayGenerator(vocab_size, array_shape).to(self.device)
        self.optimizer = optim.Adam(self.model.parameters(), lr=0.001)
        self.criterion = nn.MSELoss()

    def train(self, data_pairs: List[Tuple[int, np.ndarray]], epochs: int = 10, 
              batch_size: int = 32, validation_split: float = 0.1) -> List[Dict[str, float]]:
        try:
            split_idx = int(len(data_pairs) * (1 - validation_split))
            train_loader = DataLoader(
                ThreeDArrayDataset(data_pairs[:split_idx]), 
                batch_size=batch_size, 
                shuffle=True
            )
            val_loader = DataLoader(
                ThreeDArrayDataset(data_pairs[split_idx:]), 
                batch_size=batch_size, 
                shuffle=False
            )

            history = []
            for epoch in range(epochs):
                self.model.train()
                train_loss = 0.0

                for tokens, arrays in train_loader:
                    tokens = tokens.to(self.device)
                    arrays = arrays.to(self.device)

                    self.optimizer.zero_grad()
                    outputs = self.model(tokens)
                    loss = self.criterion(outputs, arrays)
                    loss.backward()
                    torch.nn.utils.clip_grad_norm_(self.model.parameters(), 1.0)
                    self.optimizer.step()
                    train_loss += loss.item()

                avg_train_loss = train_loss / len(train_loader)

                self.model.eval()
                val_loss = 0.0
                with torch.no_grad():
                    for tokens, arrays in val_loader:
                        tokens = tokens.to(self.device)
                        arrays = arrays.to(self.device)
                        outputs = self.model(tokens)
                        val_loss += self.criterion(outputs, arrays).item()

                avg_val_loss = val_loss / len(val_loader)
                history.append({'epoch': epoch+1, 'train_loss': avg_train_loss, 'val_loss': avg_val_loss})

                # Clear cache if memory is low
                if MemoryMonitor.get_memory_usage()['available_mb'] < 500:
                    MemoryMonitor.clear_cache()

            return history
        except RuntimeError as e:
            if 'out of memory' in str(e).lower():
                MemoryMonitor.clear_cache()
                raise RuntimeError('GPU out of memory. Reduce batch_size or array dimensions.')
            raise

    def saveWeights(self, filepath: str = 'model_weights.pth') -> None:
        try:
            torch.save({
                'model_state': self.model.state_dict(),
                'optimizer_state': self.optimizer.state_dict(),
                'vocab_size': self.vocab_size,
                'array_shape': self.array_shape
            }, filepath)
        except Exception as e:
            raise RuntimeError(f'Failed to save weights: {str(e)}')

    def loadWeights(self, filepath: str = 'model_weights.pth') -> None:
        try:
            checkpoint = torch.load(filepath, map_location=self.device)
            self.model.load_state_dict(checkpoint['model_state'])
            self.optimizer.load_state_dict(checkpoint['optimizer_state'])
        except Exception as e:
            raise RuntimeError(f'Failed to load weights: {str(e)}')

    def generate(self, tokens: Union[int, List[int]], num_samples: Optional[int] = None) -> np.ndarray:
        try:
            self.model.eval()
            with torch.no_grad():
                if isinstance(tokens, int):
                    tokens_tensor = torch.tensor([tokens] * (num_samples or 1), device=self.device)
                else:
                    tokens_tensor = torch.tensor(tokens, device=self.device)
                return self.model(tokens_tensor).cpu().numpy()
        except Exception as e:
            raise RuntimeError(f'Generation failed: {str(e)}')
